    function ensureRemoteNavSlots(root) {
      if (!root) return null;
      const nativeNav = root.querySelector('a[href*="customizations"]') || root.querySelector(NEW_CONV_SELECTOR);
      if (!nativeNav) return null;
      let band = nativeNav;
      while (band.parentElement && band.parentElement !== root) band = band.parentElement;
      if (band.parentElement !== root) return null;
      let toolsSlot = root.querySelector(":scope > #bg-remote-tools-slot");
      if (!toolsSlot) {
        toolsSlot = document.createElement("div");
        toolsSlot.id = "bg-remote-tools-slot";
      }
      if (band.nextElementSibling !== toolsSlot) band.after(toolsSlot);
      let switchSlot = root.querySelector(":scope > #bg-remote-experience-slot");
      if (!switchSlot) {
        switchSlot = document.createElement("div");
        switchSlot.id = "bg-remote-experience-slot";
      }
      if (toolsSlot.nextElementSibling !== switchSlot) toolsSlot.after(switchSlot);
      return { toolsSlot, switchSlot };
    }
    function ensureExperienceSwitch(sidebar) {
      const root = sidebar || document.querySelector(SIDEBAR_SELECTOR);
      if (!root) return;
      const pills = document.querySelectorAll("#gemini-experience-switch");
      const pill = pills[0] ?? buildExperienceSwitch();
      for (let i = 1; i < pills.length; i++) pills[i].remove();
      const slots = ensureRemoteNavSlots(root);
      if (!slots) return;
      if (pill.parentElement !== slots.switchSlot) slots.switchSlot.append(pill);
      const exp = getStoredExperience();
      if (pill.dataset.geminiExperience !== exp) {
        markExperience(pill, exp, false);
      }
      updateExperienceSwitchDots(pill);
      updateSidebarDomFilter(exp);
    }
    function updateSidebarDomFilter(exp) {
      exp ||= getStoredExperience();
      const sidebar = document.querySelector(SIDEBAR_SELECTOR);
      sidebar?.querySelectorAll("[data-bg-section]").forEach((node) => node.removeAttribute("data-bg-section"));
      if (document.documentElement.dataset.geminiExperience !== exp) document.documentElement.dataset.geminiExperience = exp;
      if (sidebar && sidebar.dataset.geminiExperience !== exp) sidebar.dataset.geminiExperience = exp;
    }
